    if kind=='gamedev':
        files=[]
        for p in sorted((GAME/'godot').rglob('*')):
            if p.is_file() and '.godot' not in p.parts and p.suffix!='.uid':files.append({'path':p.relative_to(GAME/'godot').as_posix(),'sha256':sha(p),'role':'source or test support','component_ids':['iteration']})
        write(root/'gamedev-evidence.json',{'schema_version':1,'teaching_contract':'code-then-result-v1','files':files,'exclusions':[],'components':[{'id':'iteration','files':[f['path'] for f in files],'beat_ids':[b['beat_id'] for b in beats[3:-3]],'explanation':'Runtime scene ownership, player/art/collider, state/clock, level/camera/HUD, numeric reference, staged tests, keyboard tests and route helpers are explained with explicit evidence boundaries.'}],'excerpts':excerpts,'code_result_pairs':pairs})
    (root/'SCRIPT.md').write_text('# '+title+'\n\n'+''.join('## '+b['beat_id']+' — '+b['heading']+'\n\n'+(b['narration_text'] or '[Stock outro music only.]')+'\n\n' for b in beats))
    (root/'SHOTLIST.md').write_text('# Shot list\n\n'+''.join('- '+b['beat_id']+' · '+b['heading']+' · '+b['shot']['type']+'\n' for b in beats))
    (root/'FACTCHECK.md').write_text('# Source audit\n\nNarration follows CHANGE-BRIEF.md, FRICTIONAL.md and the exact new Godot source. Original physics function, tuning, level JSON and HUD are byte-identical to the starter. Mechanics: 25 checks, keyboard: 9 checks; animation: 162 independent sample points with 1,944 scalar comparisons and six staged presentation checks. No human playtest, new mini-goals, level extension or completed assignment is claimed. Gallery previews and suggested Claude prompts are labelled; their existence is not evidence of gameplay powers or a recorded chat. Capture identity, media hashes and edit decisions are checked before final assembly.\n')
    (root/'SOURCES.md').write_text((GAME/'SOURCES.md').read_text()+'\nFilm: AI-authored Liam script, local Kokoro am_onyx narration, Brutalist Claude/Godot bookends and actual native Godot captures. Human visual/film approval is pending. No paid calls or video publication.\n')
    (root/'PROMPTS.md').write_text('# Prompt provenance\n\nBear asked for one Clawd character change, all animations at the end, and two Liam explainers. The Claude composer bookends are suggested prompts, not a historical chat. No generated media service is used.\n')
    (root/'BUILD-PROMPT.md').write_text('# Rebuild this Clawd iteration film\n\nUse Brutalist godot-'+('waikthrough' if kind=='walkthrough' else 'gamedev')+' with Walker bookends and Liam. Verify source and capture hashes; preserve the original starter. Use local Kokoro, audio lock, actual normal-input Godot takes, and separately labelled diagnostic gallery. Show code then its actual result. Measure durations; never stretch gameplay. Render through scripts/build.py and the canonical remotion_scenes.py/compile.py pipeline at 3840×2160, 30 fps. Run coverage/source, frame-level visual, audio-preservation and SRT checks. Inspect all sampled frames, correct defects, record limits. Keep regular outro music only. No publishing.\n')
    (root/'SHOPPING.md').write_text('# Assets\n\nFree local pipeline only: actual Godot captures, source-backed reconstructed editor, Claude bookends, bundled fonts and regular stock outro. No paid assets or missing visual placeholders.\n')
